// Limestone / Calcare chiaro - Ray Marching STATICA (niente ubuf.u_time)
// FILOSOFIA (v2): il calcare ha colore quasi UNIFORME. Le zone scure NON sono
// roccia di colore diverso: sono OMBRE delle irregolarita'. Il chiaroscuro vero
// lo fanno gia' le normali del displacement (calcNormal su map() perturbato) e
// l'ambient occlusion del motore. Qui la texture resta chiara e uniforme e si
// limita ad ACCOMPAGNARE l'ombra nelle cavita', senza dipingere crepe finte.
// Gira DENTRO shadeSurface() -> niente definizioni di funzioni, tutto inline.
// In scope: pModel, n_model. Colori dock: u_col1 = roccia, u_col2 = fondo cavita'.

// --- fBm di CAVITA': STESSO campo del displacement (scala 6.0), cosi' lo scuro
//     cromatico cade ESATTAMENTE dove la geometria e' incavata -> l'ombra propria
//     e l'occlusione coincidono con la depressione fisica.
vec3 cp = pModel * 6.0;

float cav  = 0.0;
float camp = 0.5;
float cnrm = 0.0;

for (int oct = 0; oct < 4; oct++) {
    vec3 ip = floor(cp);
    vec3 fr = fract(cp);
    vec3 w  = fr * fr * (3.0 - 2.0 * fr);

    float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);

    float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
    float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
    float vn = mix(z0, z1, w.z);

    cav  += camp * vn;
    cnrm += camp;
    cp   *= 2.05;   // stessa lacunarita' del displacement
    camp *= 0.5;
}
cav /= cnrm;   // ~[0,1]. cav < 0.5 = cavita' (il displacement spinge in dentro).

// occlusione cromatica: solo nelle cavita' piu' profonde, dolce.
// (il chiaroscuro forte lo fa gia' la luce/AO del motore: qui solo un rinforzo)
float ambientOcc = smoothstep(0.55, 0.20, cav);   // 1 nel fondo, 0 sulle creste

// --- MICRO-GRANA ad alta frequenza: variazione di TONO, non di colore ---
vec3 gp = floor(pModel * 44.0);
float grain = fract(sin(dot(gp, vec3(12.99, 78.23, 37.71))) * 43758.5453);
grain = (grain - 0.5) * 0.06;   // +/-3%, appena percettibile

// --- COLORE: roccia quasi uniforme (u_col1), leggerissima variazione di tono.
float tone = 1.0 + grain;
vec3 rock = ubuf.u_col1 * tone;

// accompagna l'ombra nelle cavita' verso u_col2 (fondo scuro), in modo contenuto:
// il grosso dello scuro arriva da luce+AO, questo evita che le cavita' schiariscano
// troppo per via del solo termine ambient.
rock = mix(rock, ubuf.u_col2, ambientOcc * 0.35);

textureCol = rock;

